{{range .Connections}}
<tr class="{{if .Selected}}selected{{end}}"><td><a href="/ui2/ws?exchange={{.Exchange}}" hx-get="/ui2/ws?exchange={{.Exchange}}&amp;direction={{$.P.Direction}}&amp;opcode={{$.P.Opcode}}&amp;payload={{$.P.Payload}}" hx-target="#rows" hx-swap="outerHTML" hx-push-url="true" aria-pressed="{{if .Selected}}true{{else}}false{{end}}">#{{.Exchange}}</a></td><td title="{{if .TLS}}wss{{else}}ws{{end}}://{{.Host}}:{{.Port}}{{.Path}}">{{if .TLS}}wss{{else}}ws{{end}}://{{.Host}}:{{.Port}}{{.Path}}</td><td>{{.Messages}}</td><td>{{.Sent}}</td><td>{{.Received}}</td><td>{{if .Live}}live{{else}}—{{end}}</td><td>{{.Age}}</td></tr>
{{else}}<tr><td colspan="7" class="meta">No WebSocket connections relayed.</td></tr>{{end}}
