</table>
<h3>Frames <span class="meta">{{len .Rows}} shown of {{.Total}} stored</span></h3>
<form id="ws-filter" class="ws-bar" hx-get="/ui2/ws" hx-target="#rows" hx-swap="outerHTML" hx-push-url="true" hx-trigger="submit, change">
{{if .P.Exchange}}<input type="hidden" name="exchange" value="{{.P.Exchange}}">{{end}}
