<option value="client_to_server"{{if eq .P.Direction "client_to_server"}} selected{{end}}>Sent</option>
<option value="server_to_client"{{if eq .P.Direction "server_to_client"}} selected{{end}}>Received</option></select>
<select name="opcode" aria-label="Filter by opcode"><option value="">Any opcode</option>
{{range $o := (list "text" "binary" "ping" "pong" "close")}}<option value="{{$o}}"{{if eq $o $.P.Opcode}} selected{{end}}>{{$o}}</option>{{end}}</select>
<input type="search" name="payload" value="{{.P.Payload}}" aria-label="Filter frames by payload text" placeholder="payload contains…">
<button type="submit">Filter</button>
{{if .HasFilter}}<a class="btn" href="/ui2/ws{{if .P.Exchange}}?exchange={{.P.Exchange}}{{end}}" hx-get="/ui2/ws{{if .P.Exchange}}?exchange={{.P.Exchange}}{{end}}" hx-target="#rows" hx-swap="outerHTML" hx-push-url="true">clear filters</a>{{end}}
</form>
<div class="ws-split">
<div class="ws-list">
<table class="ws-t">
<thead><tr><th scope="col">#</th><th scope="col">URL</th><th scope="col">Dir</th><th scope="col">Opcode</th><th scope="col">Length</th><th scope="col">Edited</th><th scope="col">Notes</th><th scope="col">TLS</th><th scope="col">Listener port</th><th scope="col">WS id</th><th scope="col">Age</th></tr></thead>
<tbody id="rows-body">
{{range .Rows}}
<tr class="{{if .Opened}}selected{{end}}" data-id="{{.ID}}" hx-get="/ui2/ws/frame/{{.ID}}" hx-target="#ws-detail" hx-swap="innerHTML" hx-push-url="false"><td>{{.ID}}</td><td title="{{.URL}}">{{if .URL}}{{.URL}}{{else}}—{{end}}</td><td title="{{.Direction}}">{{if .Sent}}<span class="ws-sent">→ sent</span>{{else}}<span class="ws-recv">← recv</span>{{end}}</td><td><code>{{.Opcode}}</code></td><td>{{.Len}}{{if .Truncated}} <span class="badge">truncated</span>{{end}}</td><td>{{if .Edited}}edited{{else}}—{{end}}</td><td title="{{.Note}}">{{if .Note}}{{.Note}}{{else}}—{{end}}</td><td>{{if .TLS}}TLS{{else}}—{{end}}</td><td>{{if .ListenerPort}}{{.ListenerPort}}{{else}}—{{end}}</td><td>#{{.SocketID}}</td><td>{{.Age}}</td></tr>
{{else}}<tr><td colspan="11" class="meta">{{if .HasFilter}}No frames match the filters.{{else if .P.Exchange}}No frames on this connection.{{else}}No frames.{{end}}</td></tr>{{end}}
</tbody>
</table>
</div>
<div id="ws-detail" role="region" aria-label="Selected frame" aria-live="polite">{{if .FrameView}}{{template "ws_frame.html" .FrameView}}{{else if .Selected}}<p class="meta">Select a frame, or <a href="/ui2/ws/handshake/{{.Selected.Exchange}}" hx-get="/ui2/ws/handshake/{{.Selected.Exchange}}" hx-target="#ws-detail" hx-swap="innerHTML">view the handshake of #{{.Selected.Exchange}}</a>.</p>{{else}}<p class="meta">Select a frame to read its payload, or a connection to narrow the table.</p>{{end}}</div>
</div>
</div>
