// scopeKinds decodes the GET /api/scope response (the TS ScopeInfo shape:
// {allow_all, rules:[{kind:"Include"|"Exclude", host}], empty}) into a
// lowercased kind -> pattern list.
func scopeKinds(t *testing.T, rec *httptest.ResponseRecorder) map[string][]string {
	t.Helper()
	var body struct {
		AllowAll bool `json:"allow_all"`
		Rules    []struct {
			Kind string  `json:"kind"`
			Host *string `json:"host"`
		} `json:"rules"`
		Empty bool `json:"empty"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode scope response %q: %v", rec.Body.String(), err)
	}
	out := map[string][]string{}
	for _, rule := range body.Rules {
		kind := strings.ToLower(rule.Kind)
		host := ""
		if rule.Host != nil {
			host = *rule.Host
		}
		out[kind] = append(out[kind], host)
	}
	return out
}

func TestScopePostRemoveTakesARuleOutOfScope(t *testing.T) {
	s := newTestServer()
func seedUI2Exchange(t *testing.T, s *Server, request, response string) core.ExchangeID {
	t.Helper()
	reqID, err := s.store.Put([]byte(request), core.DirectionRequest)
	if err != nil {
		t.Fatal(err)
	}
	respID, err := s.store.Put([]byte(response), core.DirectionResponse)
	if err != nil {
		t.Fatal(err)
	}
	status := uint16(0)
	if len(response) >= 12 {
		if n, err := strconv.Atoi(strings.TrimSpace(response[9:12])); err == nil {
			status = uint16(n)
		}
	}
	host := "h.test"
	for _, line := range strings.Split(request, "\r\n") {
		if strings.HasPrefix(strings.ToLower(line), "host:") {
			host = strings.TrimSpace(line[5:])
		}
	}
	ex := &core.Exchange{
		Host: host, Port: 80, Method: firstLineMethod(request), Path: firstLinePath(request),
		Status: &status, Request: core.MsgPtr(reqID), Response: &respID, Source: core.SourceProxy,
	}
	s.store.AddExchange(ex)
	return ex.ID
}

// ---- Logger capture controls -------------------------------------------------------------------

// ui2LoggerAction posts one capture action and returns the re-rendered fragment.
func ui2LoggerAction(t *testing.T, s *Server, action, form string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodPost, "/ui2/logger/"+action, strings.NewReader(form))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	rec := httptest.NewRecorder()
	s.mux.ServeHTTP(rec, req)
	return rec
}

// The Logger page surfaces the capture axis: every tool's recording state, a toggle per tool, the
// off-capture disclosure, and the not-captured counters.
}

// The search carryover survives a reviewed toggle: the sheet and the re-rendered fragment keep it.
func TestUI2LoggerActionKeepsSearch(t *testing.T) {
	s := newTestServer()
	token, sheet := ui2LoggerReview(t, s, "capture-decoder-off", "search=needleterm")
	if !strings.Contains(sheet, "needleterm") {
		t.Errorf("review sheet dropped the search carryover")
	}
	rec := ui2LoggerAction(t, s, "capture-run", "token="+token+"&tool=decoder&on=false&search=needleterm")
	if rec.Code != http.StatusOK {
		t.Fatalf("toggle = %d", rec.Code)
	}
	if !strings.Contains(rec.Body.String(), "needleterm") {
		t.Errorf("re-rendered fragment dropped the search carryover")
	}
}

// ---- Scope editing -----------------------------------------------------------------------------

// ui2ScopeConfirm posts the confirm step and extracts the minted one-time token from the review
// fragment, mirroring the scanner launch helper.
func ui2ScopeConfirm(t *testing.T, s *Server, form string) (string, string) {
	t.Helper()
