// Unit 22 e2e: Logger detail/annotate/capture review, WS frame filters + frame view.
const { chromium } = require('playwright');
const OUT = __dirname;
const BASE = 'http://127.0.0.1:19220';

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const failures = [];
  const check = (cond, msg) => { if (!cond) failures.push(msg); console.log((cond ? 'ok   ' : 'FAIL ') + msg); };
  for (const width of [1280, 390]) {
    const ctx = await browser.newContext({ viewport: { width, height: 900 } });
    const page = await ctx.newPage();
    const errors = [];
    page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
    page.on('pageerror', (e) => errors.push(String(e)));
    page.on('response', (r) => { if (r.status() >= 400 && r.url().startsWith(BASE)) errors.push(r.status() + ' ' + r.url()); });

    // ---- Logger ----
    await page.goto(BASE + '/ui2/logger');
    const rows = page.locator('#rows-body tr.lg-row');
    check(await rows.count() > 0, `[${width}] logger has rows`);
    await rows.first().click();
    await page.waitForSelector('#logger-detail [data-open]');
    check(await page.locator('#logger-detail pre.msg').count() > 0, `[${width}] detail shows request/response`);
    const note = 'e2e note ' + width;
    await page.fill('#logger-detail input[name="comment"]', note);
    await page.selectOption('#logger-detail select[name="highlight"]', 'green');
    await page.click('#logger-detail button:has-text("Save annotation")');
    await page.waitForSelector('#logger-note');
    check((await page.textContent('#logger-note')).includes('annotation saved'), `[${width}] annotation saved note`);
    check((await page.textContent('#rows-body')).includes(note), `[${width}] annotated comment shows in the table`);
    await page.screenshot({ path: `${OUT}/logger-detail-${width}.png`, fullPage: false });

    // view filter: status class "no response" -> empty or narrower
    await page.selectOption('#logger-view select[name="v_status"]', '2');
    await page.waitForFunction(() => location.search.includes('v_status=2'));
    check(true, `[${width}] status filter pushed to URL`);

    // capture settings through review: row limit
    await page.click('details.lg-capture summary');
    await page.fill('input[name="capacity"]', String(5000 + width));
    await page.click('button:has-text("review capture filter")');
    await page.waitForSelector('button:has-text("Confirm filter"):not([disabled])');
    check((await page.textContent('#rows')).includes('"capacity":' + (5000 + width)), `[${width}] review binds the row limit`);
    await page.screenshot({ path: `${OUT}/logger-review-${width}.png` });
    await page.click('button:has-text("Confirm filter")');
    await page.waitForSelector('#logger-view');
    check((await page.textContent('#rows')).includes('row limit ' + (5000 + width)), `[${width}] row limit applied`);

    // ---- WebSockets ----
    await page.goto(BASE + '/ui2/ws');
    const all = await page.locator('#rows-body tr[data-id]').count();
    check(all >= 4, `[${width}] ws has frames (${all})`);
    await page.selectOption('#ws-filter select[name="direction"]', 'server_to_client');
    await page.waitForFunction(() => location.search.includes('direction=server_to_client'));
    await page.waitForTimeout(300);
    const recv = await page.locator('#rows-body tr[data-id]').count();
    check(recv > 0 && recv < all, `[${width}] direction filter narrows frames (${recv} of ${all})`);
    await page.locator('#rows-body tr[data-id]').first().click();
    await page.waitForSelector('#ws-detail [data-open]');
    check(await page.locator('#ws-payload').count() === 1, `[${width}] frame view shows payload`);
    const payloadHTML = await page.innerHTML('#ws-detail');
    check(!payloadHTML.includes('<b>welcome</b>'), `[${width}] payload markup is escaped`);
    await page.screenshot({ path: `${OUT}/ws-frame-${width}.png` });
    // close frame view
    await page.goto(BASE + '/ui2/ws?opcode=close');
    await page.locator('#rows-body tr[data-id]').first().click();
    await page.waitForSelector('#ws-detail [data-open]');
    check((await page.textContent('#ws-detail')).includes('1000'), `[${width}] close code shown`);
    await page.click('#ws-detail a:has-text("Handshake")');
    await page.waitForSelector('#ws-detail h3:has-text("Handshake")');
    check((await page.textContent('#ws-detail')).includes('Switching Protocols'), `[${width}] handshake shown`);
    await page.screenshot({ path: `${OUT}/ws-handshake-${width}.png` });

    check(errors.length === 0, `[${width}] no console errors / 4xx / 5xx: ${errors.join(' | ')}`);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
    check(!overflow, `[${width}] no horizontal page overflow`);
    await ctx.close();
  }
  await browser.close();
  console.log(failures.length ? `${failures.length} FAILURES` : 'ALL PASS');
  process.exit(failures.length ? 1 : 0);
})();

